---@class TranslationService : IConnectorMsgHandler
local TranslationService = class("TranslationService", require "engine_base.connector.IConnectorMsgHandler")
---@type IConnectorDispatch
local ConnectorDispatch = T(Global, "ConnectorDispatch")

local Connector2GameMsgType = {
    PrivateMsg = 30011, ---接收到私聊消息
    TeamMsg = 30012, ---接收到队伍内消息
    GameMsg = 30013, ---接收到同游戏内消息
    WorldMsg = 30014, ---接收到全服消息
    GroupMsg = 30015, ---接收到聊天组消息
    LangGroupMsg = 30016, ---接收到同语言聊天组消息
    SameServerMsg = 31001 ---同服消息
}

function TranslationService:initMsgFunc()
    self:registerMsgFunc(Connector2GameMsgType.PrivateMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.TeamMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.GameMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.WorldMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.GroupMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.LangGroupMsg, self.onCheckTranMsg)
    self:registerMsgFunc(Connector2GameMsgType.SameServerMsg, self.onCheckTranMsg)
end

function TranslationService:onCheckTranMsg(type, targets, data)
    if type == Connector2GameMsgType.SameServerMsg or string.find(data, "translation") then
        local info = json.decode(data)
        if info.type ~= Define.ChatMsgType.TextMsg then
            return false
        end
        local translations = {}
        for _, v in pairs(info.data.translation or {}) do
            for key, lang in pairs(v) do
                translations[key] = lang
            end
        end
        local players = {}
        local needTranslation = {}
        if #targets == 0 or tostring(targets[1]) == "0" then
            for _, player in pairs(PlayerManager:getPlayers()) do
                if not PlayerManager:isAIPlayer(player) then
                    if player.translationEnable then
                        local lang = player:getLanguage()
                        if translations[lang] then
                            table.insert(players, player)
                        else
                            if not needTranslation[lang] then
                                needTranslation[lang] = {}
                            end
                            table.insert(needTranslation[lang], player)
                        end
                    else
                        table.insert(players, player)
                    end
                end
            end
        else
            for _, userId in pairs(targets) do
                local player = PlayerManager:getPlayerByUserId(userId)
                if player then
                    if player.translationEnable then
                        local lang = player:getLanguage()
                        if translations[lang] then
                            table.insert(players, player)
                        else
                            if not needTranslation[lang] then
                                needTranslation[lang] = {}
                            end
                            table.insert(needTranslation[lang], player)
                        end
                    else
                        table.insert(players, player)
                    end
                end
            end
        end
        local haveData = data and #data > 0
        for _, player in pairs(players) do
            local lang = player:getLanguage()
            info.data.translation = player.translationEnable and translations[lang] or nil
            local builder = DataBuilder.new()
            builder:addParam("type", type)
            if haveData then
                builder:addParam("data", json.encode(info))
            end
            local result = builder:getListData()
            PacketSender:sendLuaCommonData(player.rakssid, "ConnectorMsg", result)
        end
        for lang, playerArr in pairs(needTranslation) do
            WebService:STryTranslate(info.sendId, info.data.content, function(content, code)
                if code == 1 then
                    for _, v in pairs(content) do
                        for _, text in pairs(v) do
                            info.data.translation = text
                            break
                        end
                    end
                else
                    info.data.translation = nil
                end
                local builder = DataBuilder.new()
                builder:addParam("type", type)
                if haveData then
                    builder:addParam("data", json.encode(info))
                end
                local result = builder:getListData()
                for _, player in pairs(playerArr) do
                    PacketSender:sendLuaCommonData(player.rakssid, "ConnectorMsg", result)
                end
            end, nil, { lang })
        end
        return true
    end
end

ConnectorDispatch:registerHandler(T(Global, "TranslationService", TranslationService.new()))